<?php $dir = __DIR__."/app/Services"; $it = new RecursiveIteratorIterator(new RecursiveDirectoryIterator($dir)); $loops = 0; foreach($it as $f) { if($f->getExtension() == "php") { $c = file_get_contents($f->getPathname()); if(preg_match("/foreach\s*\(.*?\)\s*\{[^}]*(->save\(|->create\(|::create\(|::find\(|->update\(|->delete\()[^}]*\}/s", $c)) { $loops++; echo $f->getFilename()."\n"; } } } echo "DB Loops found: $loops\n";
